153	                        + " FROM reading WHERE equipment_id = ? ORDER BY sampled_at ASC, reading_id ASC",
154	                READING_MAPPER, equipmentId);
155	    }
156	
157	    // ---------- 修订历史 ----------
158	
159	    public void insertRevision(String equipmentId, String readingId, int revisionNo,
160	                               long cumulativeMinutes, String requestId, Instant createdAt) {
161	        jdbc.update("INSERT INTO reading_revision (equipment_id, reading_id, revision_no,"
162	                        + " cumulative_minutes, request_id, created_at) VALUES (?, ?, ?, ?, ?, ?)",
163	                equipmentId, readingId, revisionNo, cumulativeMinutes, requestId, utc(createdAt));
